public(package) fun handle_mint<MarketType, CoinType>(
    self: &mut Market<MarketType>,
    obligation: ID,
    coin: Coin<CoinType>,
    now: u64,
): (u64, u64) {
    assert!(coin.value() != 0, error::no_zero_amount());

    let name = type_name::with_defining_ids<CoinType>();
    let deposit_amount = coin.value();

    let asset = self.assets.load_mut_by_type(name);
    assert!(!asset.deposit_paused(), error::deposit_paused_for_asset());

    let asset_config = asset.asset_config();

    let reserve = accrue_interest<MarketType>(name, &mut self.reserves, asset_config, asset.interest_model(), now);

    // technically should be in stable coin value, but keep it this way for now
    assert!(
        !reserve.deposit_limit_breached<MarketType>(
            deposit_amount,
            asset_config.max_deposit_amount(),
        ),
        error::market_deposit_limit_exceeded(),
    );

    let ctoken = reserve.mint_ctokens(coin);
    let ctoken_amount = ctoken.value();

    // now handle obligation related
    let obligation = self.obligations.borrow_mut(obligation);
    assert!(
        obligation.market_id() == self.id.uid_as_inner(),
        error::obligation_from_different_market(),
    );
    obligation.deposit_ctoken<MarketType, CoinType>(ctoken);

    // update rate limit deposit 
    let emode = self.emode_group_registry.borrow_mut_emode(obligation.emode_group(), type_name::with_defining_ids<CoinType>());
    emode.borrow_mut_deposit_limiter().reduce_outflow(now, deposit_amount);

    (ctoken_amount, obligation.ctoken_amount_by_coin(name))
}

public(package) fun handle_withdraw<MarketType, CoinType>(
    self: &mut Market<MarketType>,
    obligation_id: ID,
    ctoken_amount: u64,
    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
    now: u64,
    ctx: &mut TxContext,
): (Coin<CoinType>, u64) {
    assert!(ctoken_amount != 0, error::no_zero_amount());

    let name = type_name::with_defining_ids<CoinType>();

    let asset = self.assets.load_by_type(name);
    assert!(!asset.withdraw_paused(), error::withdraw_paused_for_asset());


    let obligation = self.obligations.borrow_mut(obligation_id);
    assert!(obligation.market_id() == self.id.uid_as_inner(), error::obligation_from_different_market());

    // refresh all interest
    let emode_group = self.emode_group_registry.borrow_emode_group_mut(obligation.emode_group());
    refresh_obligation_assets_interest<MarketType>(&self.assets, emode_group, &mut self.reserves, obligation, now);

    let ctoken = obligation.withdraw_ctokens(ctoken_amount);
    let ctokens_left = obligation.ctoken_amount_by_coin(name);

    // TODO: if the asset is not collateral, skip obligation safety check
    let is_obligation_safe = is_obligation_safe(
        self.emode_group_registry.borrow_emode_group(obligation.emode_group()),
        &self.reserves,
        &self.ema_spot_tolerance,

        obligation,
        coin_decimals_registry,
        x_oracle,
        clock,
    );
    assert!(is_obligation_safe, error::obligation_not_safe_after_operation());

    let reserve = self.reserves.load_mut_by_type(name);
    let deposit = reserve.burn_ctokens<MarketType, CoinType>(ctoken.into_coin(ctx));

    // rate limit deposit withdraw
    let emode = self.emode_group_registry.borrow_mut_emode(obligation.emode_group(), type_name::with_defining_ids<CoinType>());
    emode.borrow_mut_deposit_limiter().add_outflow(
        now,
        deposit.value(),
    );

    // update adl

    // use ceiling, slighly more 
    let total_deposit = reserve.total_deposit_plus_interest().ceil();
    let adl = dynamic_field::borrow_mut<ADLRegistryKey, AutoDeleverageRegistry>(&mut self.id, ADLRegistryKey {});
    adl.try_stop_collateral_deleverage<CoinType>(type_name::with_defining_ids<MarketType>(), total_deposit);



    (deposit.into_coin(ctx), ctokens_left)
}

/// @title Module for flash loan from base asset pools
module protocol::flash_loan;

use std::type_name::{Self, TypeName};
use std::string::String;

use sui::coin::Coin;
use sui::clock::Clock;

use sui::event::emit;

use x_oracle::x_oracle::XOracle;
use x_oracle::user_oracle::get_price;

use protocol::app::{ProtocolApp, PackageCallerCap};
use protocol::coin_decimals_registry::CoinDecimalsRegistry;
use protocol::market::{Market, FlashLoan};
use protocol::value::coin_value;

public struct BorrowFlashLoanEvent has copy, drop {
    market: TypeName,
    borrower: address,
    asset: TypeName,
    amount: u64,
    fee: u64,
}

public struct RepayFlashLoanEvent has copy, drop {
    market: TypeName,
    borrower: address,
    asset: TypeName,
    amount: u64,
    fee: u64,
}

public fun borrow_flash_loan<MarketType, CoinType>(
    app: &ProtocolApp,
    cap: &PackageCallerCap,

    market: &mut Market<MarketType>,

    emode_group: u8,
    amount: u64,

    ctx: &mut TxContext,
): (Coin<CoinType>, FlashLoan<MarketType, CoinType>) {
    app.ensure_version_matches();
    app.validate_market<MarketType>(market);

    app.ensure_has_permission(object::id(cap), protocol::whitelist_admin::flash_loan());

    borrow_flash_loan_inner<MarketType, CoinType>(market, amount, emode_group, ctx)
}

/// @notice Repay flash loan to market
/// @dev This is the only method to repay flash loan, consume the flash loan hot potato object
/// @param version The version control object, contract version must match with this
/// @param market The market object, it contains base assets, and related protocol configs
/// @param coin The coin object to repay
/// @param loan The flash loan hot potato object, which contains the borrowed amount and fee
/// @ctx The SUI transaction context object
/// @custom:T The type of asset to repay
public fun repay_flash_loan<MarketType, CoinType>(
    app: &mut ProtocolApp,
    market: &mut Market<MarketType>,

    coin: Coin<CoinType>,
    loan: FlashLoan<MarketType, CoinType>,

    ctx: &mut TxContext,
) {
    app.ensure_version_matches();
    app.validate_market<MarketType>(market);

    // Emit the repay flash loan event
    emit(RepayFlashLoanEvent {
        market: type_name::with_defining_ids<MarketType>(),
        borrower: ctx.sender(),
        asset: type_name::with_defining_ids<CoinType>(),
        // amount is total repay coin amount
        amount: coin.value(),
        fee: loan.fee(),
    });

    let referral = app.referral_mut();
    // Put the asset back to the market and consume the flash loan hot potato object
    market.repay_flash_loan(coin, loan, referral, std::option::none(), ctx);
}

public fun repay_flash_loan_increase_referral_qualification<MarketType, CoinType>(
    app: &mut ProtocolApp,
    market: &mut Market<MarketType>,

    coin: Coin<CoinType>,
    loan: FlashLoan<MarketType, CoinType>,

    maybe_referral_code: Option<String>,

    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,

    ctx: &mut TxContext,
) {
    app.ensure_version_matches();
    app.validate_market<MarketType>(market);

    // Emit the repay flash loan event
    emit(RepayFlashLoanEvent {
        market: type_name::with_defining_ids<MarketType>(),
        borrower: ctx.sender(),
        asset: type_name::with_defining_ids<CoinType>(),
        // amount is total repay coin amount
        amount: coin.value(),
        fee: loan.fee(),
    });

    let referral = app.referral_mut();
    track_referral(referral, ctx.sender(), loan.loan_amount(), type_name::with_defining_ids<CoinType>(), coin_decimals_registry, x_oracle, clock);
    let maybe_referral_code = referral.try_map_referral_code(ctx.sender(), maybe_referral_code);

    // Put the asset back to the market and consume the flash loan hot potato object
    market.repay_flash_loan(coin, loan, referral, maybe_referral_code, ctx);
}

fun borrow_flash_loan_inner<MarketType, CoinType>(
    market: &mut Market<MarketType>,
    amount: u64,
    emode_group: u8,
    ctx: &mut TxContext,
): (Coin<CoinType>, FlashLoan<MarketType, CoinType>) {
    assert!(!market.has_circuit_break_triggered(), protocol::error::market_under_circuit_break());

    let (coin, flash_loan) = market.borrow_flash_loan(emode_group, amount, ctx);

    // Emit the borrow flash loan event
    emit(BorrowFlashLoanEvent {
        market: type_name::with_defining_ids<MarketType>(),
        borrower: ctx.sender(),
        asset: type_name::with_defining_ids<CoinType>(),
        fee: flash_loan.fee(),
        amount,
    });

    // Return the borrowed coin object and the flash loan hot potato object
    (coin, flash_loan)
}

fun track_referral(
    referral: &mut protocol::referral::Referral,

    who: address,

    token_amount: u64,
    token_type: TypeName,

    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
) {
    if (referral.is_qualified_to_create_referral_code(who)) return;

    let decimals = coin_decimals_registry.decimals(token_type);
    // always use usd price
    let usd_price = get_price(x_oracle, token_type, x_oracle::x_oracle::usd(), clock);
    let collateral_value_usd = coin_value(usd_price, math::float::from(token_amount), decimals);

    referral.increase_usd_qualification(who, collateral_value_usd.floor());
}

#[test_only]
public fun borrow_flash_loan_against_group<MarketType, CoinType>(
    market: &mut Market<MarketType>,
    amount: u64,
    emode_group: u8,
    ctx: &mut TxContext,
): (Coin<CoinType>, FlashLoan<MarketType, CoinType>) {
    borrow_flash_loan_inner<MarketType, CoinType>(market, amount, emode_group, ctx)
}

